import {blendSettings,blendAction,bindBlends,batchRecipeDetails,recipeSelect,ingredientSummary} from './blend-view.js';
import {coffeeSettings,coffeeVisibilityAction} from './coffee-view.js';
import {roastBatchesPage,completeRoastForm} from './roast-view.js';
import {profitPage,profitAction,bindProfit,setProfit,shippingSummary} from './profit-view.js';
import {en as t} from './i18n.js';
import {selectOrders,orderStatus,isOrderStock,orderAllocationStocks} from './order-view.js';
import {orderHealth,statusSummary,statusLegend} from './status-view.js';
import {routeForHash,settingsTabs} from './navigation.js';
import {planPage} from './plan-view.js';
import {todayPage} from './today-view.js';
import {bindCoffeeRoast} from './coffee-roast-view.js';
import {stockPage as roastedStockPage,addRoastedStockForm,stockActions,hasStock,compareStockAge,selectStocks} from './stock-view.js';
import {greenPage,greenAction,bindGreen} from './green-view.js';
import {productsPage,productAction,bindProducts} from './products-view.js';
let orderFilters={sort:'newest',source:'',status:'',fulfillment:'',payment:'',production:'',search:''};
const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const initialRoute=routeForHash(location.hash);
if(initialRoute.hash)history.replaceState(null,'',initialRoute.hash);
let S,session,view=initialRoute.view,tab=initialRoute.tab,busy=false,disconnected=false,filters={balance:'on-hand',use:'brew',coffee:'',location:'',form:'',reservation:'',readiness:'',date:''};
const grams=n=>new Intl.NumberFormat('en',{maximumFractionDigits:3}).format((n||0)/1000)+' g', kg=n=>new Intl.NumberFormat('en',{maximumFractionDigits:2}).format((n||0)/1e6)+' kg';
const date=(s,time=false)=>s?new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Tokyo',day:'numeric',month:'short',...(time?{hour:'2-digit',minute:'2-digit'}:{})}).format(new Date(s)):'Not set';
const localInput=s=>s?new Date(new Date(s).getTime()+9*3600000).toISOString().slice(0,16):'';
const iso=s=>s?new Date(s+':00+09:00').toISOString():null;
const clock=()=>S?.clock||new Date().toISOString();
const plus=days=>new Date(new Date(clock()).getTime()+days*86400000).toISOString();
const badge=(text,kind='')=>`<span class="badge ${kind}">${esc(text)}</span>`;
const btn=(label,action,data={},cls='secondary')=>`<button class="${cls}" data-action="${action}" ${Object.entries(data).map(([k,v])=>`data-${k}="${esc(v)}"`).join(' ')}>${label}</button>`;
const empty=(title,body='')=>`<div class="empty"><span>◌</span><h3>${esc(title)}</h3><p>${esc(body)}</p></div>`;
const options=(items,value='',blank=false)=>`${blank?'<option value="">Select…</option>':''}${items.map(([id,name])=>`<option value="${esc(id)}" ${String(id)===String(value)?'selected':''}>${esc(name)}</option>`).join('')}`;
const co=(value='',blank=false)=>options(S.coffees.filter(c=>!c.archived||c.id===value).map(c=>[c.id,c.name+' · '+c.profile]),value,blank);
const lo=(value='roastery')=>options(S.locations.map(l=>[l.id,l.name]),value);
const pa=(value='',blank=false)=>options(S.packages.map(p=>[p.id,p.name+' · '+grams(p.weight_mg)]),value,blank);
const field=(label,name,type='text',value='',attrs='')=>`<label class="field">${esc(label)}<input name="${name}" type="${type}" value="${esc(value)}" ${attrs}></label>`;
const select=(label,name,opts)=>`<label class="field">${esc(label)}<select name="${name}">${opts}</select></label>`;
const area=(label,name,value='',attrs='')=>`<label class="field wide">${esc(label)}<textarea name="${name}" ${attrs}>${esc(value)}</textarea></label>`;
const notice=text=>`<div class="notice">${text}</div>`;
const admin=()=>S?.user.role==='admin';
function toast(message,error=false){const el=$('#toast');el.textContent=message;el.className='show '+(error?'error':'');setTimeout(()=>el.className='',6000)}
async function api(path,data,key){const response=await fetch('/api/'+path,{method:data?'POST':'GET',headers:{'Content-Type':'application/json',...(session?.csrf?{'X-CSRF-Token':session.csrf}:{}),...(key?{'Idempotency-Key':key}:{})},...(data?{body:JSON.stringify(data)}:{})});let r;try{r=await response.json()}catch{throw Error('Server returned an unreadable response. Refresh before retrying.')}if(!response.ok){if(response.status===401){session=null;S=null;loginScreen()}throw Error(r.error||'Request failed')}return r}
async function refresh(render=true){try{S=await api('state');if(view==='profit')setProfit(await api('profit'));disconnected=false;if(render)draw()}catch(e){disconnected=true;if(render&&S)draw();else if(!S)toast(e.message,true);throw e}}
function modal(title,body,onSubmit,submit='Save',width=''){const el=$('#modal');el.className=width;el.innerHTML=`<form><header><div><div class="modal-brand">${logo}</div><h2>${esc(title)}</h2></div><button type="button" data-close aria-label="Close dialog">×</button></header><div class="modal-body">${body}<div class="form-error" role="alert"></div></div><footer><button type="button" class="secondary" data-close>Cancel</button>${onSubmit?`<button type="submit" class="primary">${esc(submit)}</button>`:''}</footer></form>`;el.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>el.close());el.querySelector('form').onsubmit=async e=>{e.preventDefault();if(busy)return;busy=true;const b=el.querySelector('[type=submit]');if(b)b.disabled=true;const requestKey=el.dataset.requestKey||(el.dataset.requestKey=crypto.randomUUID());try{await onSubmit(Object.fromEntries(new FormData(e.target)),requestKey);delete el.dataset.requestKey;el.close();await refresh();toast('Saved to the shared database.')}catch(err){el.querySelector('.form-error').textContent=err.message}finally{busy=false;if(b)b.disabled=false}};delete el.dataset.requestKey;if(!el.open)el.showModal()}
function loginScreen(){const demo=session?.demo;$('#app').innerHTML=`<main class="login"><div class="wordmark">${logo}</div><div class="login-card"><span class="eyebrow">COFFEE, FROM ROAST TO CUP</span><h1>A good day starts<br>with a clear plan.</h1><p>Sign in to your shared roastery workspace.</p><form id="login-form">${field('Username','name','text',demo?'demo':'','required autocomplete="username"')}${field('Password','password','password',demo?'walnuts-demo-only':'','required autocomplete="current-password"')}<p class="form-error" role="alert"></p><button class="primary" type="submit">${demo?'Explore isolated demo →':'Sign in →'}</button></form>${demo?notice('Fictional sample data · Fixed clock: 5 Nov 2026, 12:00 JST. Demo credentials work only in this loopback-only instance.'):'<p class="muted">First use? Create the administrator account on the server using the setup instructions.</p>'}</div><p class="muted">Walnuts Coffee · Tokyo, Japan</p></main>`;$('#login-form').onsubmit=async e=>{e.preventDefault();try{session=await api('login',Object.fromEntries(new FormData(e.target)));await refresh()}catch(err){$('#login-form .form-error').textContent=err.message}}}
const logo='<img class="brand-logo" src="/assets/walnuts-wordmark.svg" alt="Walnuts" width="1000" height="150">';
const icons={today:'◷',stock:'▦',green:'♧',batches:'◉',orders:'▤',profit:'↗',plan:'▧',settings:'⚙'};
function draw(){if(!S)return;const syncOk=Object.values(S.sync).some(s=>!s.stale);$('#app').innerHTML=`<aside class="sidebar"><a class="wordmark" href="#today" aria-label="Walnuts Roastery · Today">${logo}</a><div class="workspace">WALNUTS COFFEE <span>TOKYO, JAPAN</span></div><nav>${Object.keys(icons).map(k=>`<a href="#${k}" class="${view===k?'active':''}"><span>${icons[k]}</span>${t[k]}${k==='orders'&&S.orders.length?`<b>${S.orders.filter(o=>!o.cancelled&&o.lines.some(l=>l.unfulfilled)).length}</b>`:''}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="sync-dot ${syncOk?'ok':''}"></div><span>${S.settings.demo?'Isolated demonstration':'Manual operations ready'}<small>${syncOk?'Latest imports available':'Connections need attention'}</small></span><div class="user"><b>${esc(S.user.name.slice(0,1).toUpperCase())}</b><span>${esc(S.user.name)}<small>${esc(S.user.role)}</small></span>${btn('↗','logout',{},'icon-btn')}</div></div></aside><div class="main"><header class="topbar"><span>Operations <span class="crumb">/ ${t[view]||t.today}</span></span><div><span class="date-label">${date(clock(),true)} <small>JST</small></span>${badge(S.settings.demo?'DEMO WORKSPACE':'SHARED WORKSPACE','outline')}</div></header>${disconnected?`<div class="offline">${t.offline} ${btn('Reconnect','refresh',{},'text-btn')}</div>`:''}${S.settings.demo?'<div class="demo-strip"><b>Example data</b> Fictional coffees & orders. Clock fixed at 5 Nov 2026, 12:00 JST. Package sizes, dispatch rules and maximum capacity are examples.</div>':''}<main class="content">${({today,stock:stockPage,green:()=>greenPage(S,greenHelpers()),profit:()=>profitPage(S,greenHelpers()),batches,orders,plan:planner,settings:settingsPage}[view]||today)()}</main><footer class="page-footer">${logo}<span>Weights in grams · All times Asia/Tokyo · Rest measured in elapsed 24-hour days</span></footer></div>`;bind()}
function heading(kicker,title,description,actions=''){return `<div class="page-heading"><div><span class="eyebrow">${kicker}</span><h1>${title}</h1><p>${description}</p></div><div class="actions">${actions}</div></div>`}
function today(){return todayPage(S,{esc,kg:n=>new Intl.NumberFormat('en',{maximumFractionDigits:6}).format((n||0)/1e6)+' kg',grams,date,btn,badge,empty,heading})}
function readyLabel(r){if(r.label!=='Resting')return esc(r.label);const h=Math.max(0,Math.ceil((new Date(r.ready_at)-new Date(clock()))/3600000));return 'Ready in '+(h>=24?Math.floor(h/24)+'d '+h%24+'h':h+'h')}
function stockPage(){return roastedStockPage(S,{...greenHelpers(),readyLabel},filters)}
function batches(){return roastBatchesPage(S,greenHelpers())}
function orderControls(count){
const pretty=s=>s.toLowerCase().replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase());
const choices=key=>[...new Set(S.orders.map(o=>o[key]).filter(Boolean))].sort().map(v=>[v,pretty(v)]);
const productions=[...new Set(S.orders.flatMap(o=>o.lines.map(l=>l.status)))].sort().map(v=>[v,v]);
return `<section class="panel"><div class="filters order-filters"><label>Sort by<select data-order-filter="sort">${options([['newest','Placed: newest first'],['oldest','Placed: oldest first'],['due-first','Deadline: earliest first'],['due-last','Deadline: latest first']],orderFilters.sort)}</select></label><label>Channel<select data-order-filter="source">${options([['','All channels'],['shopify','Shopify'],['wholesale','Wholesale']],orderFilters.source)}</select></label><label>Order status<select data-order-filter="status">${options([['','All orders'],['open','Open'],['archived','Archived'],['cancelled','Cancelled']],orderFilters.status)}</select></label><label>Fulfillment status<select data-order-filter="fulfillment">${options([['','All fulfillment statuses'],...choices('fulfillment')],orderFilters.fulfillment)}</select></label><label>Payment status<select data-order-filter="payment">${options([['','All payment statuses'],...choices('payment')],orderFilters.payment)}</select></label><label>Production state<select data-order-filter="production">${options([['','All production states'],...productions],orderFilters.production)}</select></label><label>Find order<input type="search" data-order-filter="search" value="${esc(orderFilters.search)}" placeholder="Order number or item"></label>${btn('Clear filters','clear-order-filters',{},'small-btn')}</div><div class="table-foot">Showing ${count} of ${S.orders.length} orders · Dates shown in JST · Filters stay selected during refresh</div></section>`;
}
function orders(){const visible=selectOrders(S.orders,orderFilters),visibleIds=new Set(visible.map(o=>o.id)),pendingPicks=S.fulfillments.filter(f=>visibleIds.has(f.order_id));return heading('ORDER COMMITMENTS','A clear path to dispatch.','Online and wholesale commitments, with batch allocations and physical dispatch records.',btn('+ New wholesale order','new-wholesale',{},'primary')+(admin()?btn('Import order file','order-import'):''))+statusLegend()+orderControls(visible.length)+visible.map(o=>{const state=orderHealth(o,S);return `<section class="panel order-card"><div class="panel-heading commitment-header status-${state.tone}"><div><h2>${S.shop_admin_url&&/^\d+$/.test(o.id.split('/').pop())?`<a href="${esc(S.shop_admin_url+'/orders/'+o.id.split('/').pop())}" target="_blank" rel="noopener noreferrer">${esc(o.number)} ↗</a>`:esc(o.number)} ${o.source==='wholesale'?badge('Wholesale','outline'):''} ${badge(o.payment,o.payment==='PAID'?'green':'amber')} ${badge(orderStatus(o)==='archived'?'Archived':orderStatus(o)==='cancelled'?'Cancelled':'Open',o.cancelled?'red':'outline')}</h2>${statusSummary(state,esc)}${o.wholesale?`<p><b>${esc(o.wholesale.customer.business)}</b>${o.wholesale.customer.contact?' · '+esc(o.wholesale.customer.contact):''}<br>${esc(o.wholesale.status)}${o.wholesale.reference?' · PO '+esc(o.wholesale.reference):''}${o.wholesale.terms?' · '+esc(o.wholesale.terms):''}</p>`:''}<p>Placed ${o.created_at?date(o.created_at,true)+' JST':'date unavailable'} · Target ${date(o.due_at,true)} JST · ${o.source==='wholesale'?'Dispatch':'Shopify'}: ${esc(o.fulfillment||'not supplied')}<br><small>${esc(o.delivery)} ${o.notes?'· '+esc(o.notes):''}</small></p></div>${o.source==='wholesale'?`<div class="actions">${btn('Edit wholesale order','edit-wholesale',{id:o.id})}${o.wholesale.status==='CONFIRMED'&&!o.cancelled&&o.lines.some(l=>l.unfulfilled)?btn('Record dispatch','wholesale-dispatch',{id:o.id},'primary'):''}</div>`:btn('Edit local deadline','order-date',{id:o.id})}</div><div class="table-wrap"><table><thead><tr><th>Line item</th><th>Remaining</th><th>Allocated</th><th>Missing</th><th>Production state</th><th></th></tr></thead><tbody>${o.lines.map(l=>`<tr><td><b>${esc(l.title)}</b><small>${l.allocations.map(a=>esc(a.code)+' · '+esc(a.location)+' · '+grams(a.quantity_mg)+(a.package_id==='bulk'?' bulk':' packed')).join('<br>')||'No batch assigned'}</small></td><td>${l.unfulfilled} units<small>${grams(l.required_mg)}</small></td><td>${grams(l.allocated_mg)}</td><td>${grams(l.missing_mg)}</td><td>${badge(l.status,l.status.includes('Packed')?'green':l.status.includes('mapping')?'red':'amber')}</td><td>${l.kind==='unresolved'?btn('Map variant','variant',{id:l.variant_id},'small-btn'):l.unfulfilled&&l.kind==='coffee'&&!l.excluded_allocation_mg?btn('Allocate','allocate',{id:l.id},'small-btn'):''}${l.allocations.map(a=>a.package_id==='bulk'&&isOrderStock(a)?btn('Pack allocation','pack-reservation',{id:a.id},'small-btn'):'').join('')}${l.allocations.length?btn('Manage allocations','allocations',{line:l.id},'small-btn'):''}</td></tr>`).join('')}</tbody></table></div>${shippingSummary(o,greenHelpers())}</section>`}).join('')+(!visible.length?empty(S.orders.length?'No matching orders':'No imported orders',S.orders.length?'Change or clear the filters to see other orders.':'Connect Shopify or import an order file.'):'')+(pendingPicks.length?`<section class="panel"><div class="panel-heading commitment-header status-yellow"><div><h2>Confirmed shipments needing a physical pick</h2><p>Needs attention · Record the actual stock pick to reconcile these shipments.</p></div></div>${pendingPicks.map(f=>`<div class="list-row"><div><b>${esc(S.orders.find(o=>o.id===f.order_id)?.number)}</b><small>${esc(f.id)} · ${date(f.at,true)}</small></div>${btn('Record actual pick','fulfillment',{id:f.id})}</div>`).join('')}</section>`:'')}
function planner(){return planPage(S,greenHelpers())}
function settingsPage(){return heading('MAKE IT YOURS','The details behind the day.','Settings apply to new batches. Existing batches retain their policy until explicitly reviewed.')+`<div class="tabs">${Object.keys(settingsTabs).map(k=>`<button class="${tab===k?'active':''}" data-action="settings-tab" data-tab="${k}">${esc(settingsTabs[k])}${k==='exceptions'?' ('+S.issues.length+')':''}</button>`).join('')}</div>`+({coffees:settingsCoffees,products:()=>productsPage(S,greenHelpers(),{embedded:true}),mappings:settingsMappings,planning:settingsPlanning,connections:settingsConnections,exceptions:settingsExceptions,access:settingsAccess,data:settingsData}[tab]||settingsCoffees)()}
function settingsCoffees(){return blendSettings(S,greenHelpers())+coffeeSettings(S,greenHelpers())+`<div class="two-col"><section class="panel"><div class="panel-heading"><h2>Packages</h2>${admin()?btn('+ Add','package',{},'small-btn'):''}</div>${S.packages.map(p=>`<div class="list-row"><b>${esc(p.name)}</b><span>${grams(p.weight_mg)}</span></div>`).join('')||empty('No package sizes')}</section><section class="panel"><div class="panel-heading"><h2>Locations & containers</h2>${admin()?btn('+ Add','location',{},'small-btn'):''}</div>${S.locations.map(l=>`<div class="list-row">${esc(l.name)}</div>`).join('')}</section></div>`}
function settingsMappings(){return `<section class="panel"><div class="panel-heading"><h2>Shopify variants</h2><span>Stable variant IDs; bundles stay unresolved until defined</span></div>${S.variants.filter(v=>!v.id.startsWith('wholesale:')).map(v=>`<div class="list-row"><div><b>${esc(v.sku||v.id)}</b><small>${esc(v.id)}<br>${v.kind==='coffee'?esc(S.coffees.find(c=>c.id===v.coffee_id)?.name)+' · '+esc(S.packages.find(p=>p.id===v.package_id)?.name):esc(v.kind)}</small></div>${admin()?btn('Map','variant',{id:v.id},'small-btn'):''}</div>`).join('')||empty('No variants imported')}</section><section class="panel"><div class="panel-heading"><h2>Roast.World bean mappings</h2>${admin()?btn('+ Map bean','bean-map',{},'small-btn'):''}</div>${S.bean_mappings.map(m=>`<div class="list-row"><b>${esc(m.external_id)}</b><span>${esc(S.coffees.find(c=>c.id===m.coffee_id)?.name)}</span></div>`).join('')||empty('No bean mappings')}<p class="padded muted">Map the exact external bean identity to a coffee/profile for automatic import. Roasts needing information appear in Roast batches with an action to complete them.</p></section>`}
function settingsPlanning(){return `<section class="panel"><div class="panel-heading"><h2>Capacity, cadence & priorities</h2>${admin()?btn('Edit planning settings','planning-settings',{},'primary'):''}</div><div class="facts"><div><span>Working charge</span><b>${kg(S.settings.charge_mg)}</b><small>Approximately 1.2 kg confirmed by you</small></div><div><span>Maximum charge</span><b>${S.settings.max_charge_mg?kg(S.settings.max_charge_mg):'Needs confirmation'}</b><small>${S.settings.demo?'Example — confirm actual Bullet model':'Set for your actual Bullet'}</small></div><div><span>Roast weekdays</span><b>${S.settings.roast_days.map(d=>['Mon','Tue','Wed','Thu','Fri','Sat','Sun'][d]).join(', ')}</b><small>${S.settings.roast_days_confirmed?'Confirmed schedule':'Unconfirmed example schedule'}</small></div><div><span>Roast start slots (JST)</span><b>${S.settings.roast_slots.join(', ')}</b><small>One batch per configured start slot</small></div><div><span>Channel priority</span><b>${S.settings.channel_priority.join(' → ')}</b><small>For requirements sharing a deadline</small></div><div><span>Packing / delivery buffer</span><b>${S.settings.buffer_days} days</b></div><div><span>Safety buffer</span><b>${S.settings.safety_bp/100}%</b></div></div></section>`}
function settingsConnections(){return `<div class="two-col">${Object.entries(S.sync).map(([source,s])=>`<section class="panel"><div class="panel-heading"><h2>${source==='shopify'?'Shopify':source==='square'?'Square':'Roast.World'}</h2>${badge(s.configured?'Configured':'Not connected',s.configured?'green':'amber')}</div><div class="padded"><p>${source==='shopify'?'Read-only order, payment and fulfillment imports. API 2026-10.':source==='square'?'Read-only catalogue and completed receipt imports. Configure mappings, location and FIFO wall deductions under Products & POS.':'Official Aillio API. Batch imports only; RoasTime remains in control of the Bullet.'}</p><dl><dt>Last attempt</dt><dd>${s.last_attempt?date(s.last_attempt.started_at,true):'Never'}</dd><dt>Last success</dt><dd>${s.last_success?date(s.last_success,true):'Never'}</dd><dt>State</dt><dd>${esc(s.last_attempt?.message||'Waiting for server-side credentials')}</dd></dl>${admin()?btn('Sync now','sync',{source}):''}<p class="muted">Set ${source==='shopify'?'SHOPIFY_SHOP and app credentials':source==='square'?'SQUARE_ACCESS_TOKEN':'ROASTWORLD_API_KEY'} in the server environment. Secrets are never sent to this browser. See the connection guide.</p></div></section>`).join('')}</div><section class="panel"><div class="panel-heading"><h2>Square · Retail sales</h2><a href="#settings/products">Open Products & POS →</a></div><p class="padded">Review shared Shopify/Square mappings, choose the shop location, and enable FIFO retail-wall deductions from an opening-stock cutover. Café drinks are excluded through explicit non-coffee mappings; café usage remains measured locally.</p></section><section class="panel"><div class="panel-heading"><h2>Roast import start, cutover & polling</h2>${admin()?btn('Configure','connection-settings'):''}</div><p class="padded">Roast.World imports start: <b>${date(S.settings.roastworld_start_at,true)} JST</b>. Earlier unposted roasts are ignored before validation. Opening-stock cutover: <b>${date(S.settings.cutover_at,true)} JST</b>. Imported roasts before that cutover remain history-only until a physical opening count. Polling every ${Math.round(S.settings.poll_seconds/60)} minutes continues while the server is running, with no browser needed.</p></section>`}
function settingsExceptions(){return `<section class="panel"><div class="panel-heading"><h2>Reconciliation inbox</h2><span>Nothing is silently corrected</span></div>${S.issues.map(i=>`<div class="list-row issue"><span class="issue-dot">!</span><div><b>${esc(i.kind.replaceAll('_',' '))}</b><p>${esc(i.detail)}</p><small>${esc(i.source)} · ${esc(i.external_id)} · ${date(i.created_at,true)}</small></div><div>${admin()&&i.source==='roastworld'?btn('Retry import','retry-import',{id:i.external_id},'small-btn'):''}${admin()?btn('Resolve with note','resolve',{id:i.id},'small-btn'):''}</div></div>`).join('')||empty('All clear','Unmapped records, edited roasts and external shipments appear here.')}</section>`}
function settingsAccess(){return `<section class="panel"><div class="panel-heading"><h2>People & permissions</h2>${admin()?btn('+ Add account','user',{},'primary'):''}</div>${S.users.map(u=>`<div class="list-row"><div><b>${esc(u.name)}</b><small>${u.role} · ${u.active?'Active':'Disabled'}</small></div>${btn('Manage','user',{id:u.id},'small-btn')}</div>`).join('')||'<p class="padded">Only administrators can manage accounts.</p>'}<p class="padded muted">Staff can record normal operations. Administrators manage policies, imports, connections, account access and exceptional corrections. Sessions expire after 12 hours.</p></section>`}
function settingsData(){return `<section class="panel"><div class="panel-heading"><h2>Import, export & recovery</h2></div><div class="padded"><div class="quick-actions">${btn('Preview CSV import','csv')}${btn('Download CSV template','csv-template')}${btn('Export ledger JSON','export')}</div><h3>Safe backups</h3><p>The included backup command uses SQLite’s online backup API and verifies database integrity. Schedule it daily on the hosted server; copy encrypted backups off the server. Stop the app before restoring into a clean database path.</p><h3>Start with a physical count</h3><p>Configure coffees, rest rules, packages and mappings. Set a cutover timestamp. Import earlier logs as history, then count each actual batch / location / form. Open a historical batch’s zero-balance stock row to enter its count.</p><h3>Hosting & costs</h3><p>Use one small hosted server with a persistent local disk and HTTPS. Normal operation needs no paid AI or inventory platform. Server rental, offsite backups, internet and maintenance may have costs. The source includes a container, service and reverse-proxy setup.</p><h3>Deployment status</h3><p>Your workspace is served at ${esc(location.origin)}. Review Settings → Connections for the latest import status.</p></div></section>`}
function greenHelpers(){return {esc,kg,grams,date,btn,badge,empty,heading,field,select,area,notice,options,modal,api,localInput,iso,clock,admin,draw,refresh}}
function bind(){bindCoffeeRoast(S,greenHelpers());bindBlends(S,greenHelpers());bindProfit(S,greenHelpers());bindGreen(draw);bindProducts(draw);document.querySelectorAll('[data-order-filter]').forEach(el=>el.onchange=()=>{orderFilters[el.dataset.orderFilter]=el.value;draw()});document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset).catch(e=>toast(e.message,true)));document.querySelectorAll('[data-filter]').forEach(el=>el.onchange=()=>{filters[el.dataset.filter]=el.value;draw()})}
function chooseStock(kind,ids){const list=S.stocks.filter(s=>ids?ids.includes(s.id):hasStock(s)).sort(compareStockAge);if(!list.length)return toast('No matching stock. Record or transfer coffee first.',true);modal('Choose a batch',notice('Oldest roast first. Readiness and available quantities are checked again by the server.')+select('Stock scope','stock_id',options(list.map(s=>[s.id,`${s.code} · ${s.coffee} · ${s.location} · ${s.form} · ${grams(s.free_mg)} free`]))),async d=>{setTimeout(()=>stockAction(S.stocks.find(s=>s.id===d.stock_id),kind),0)},'Continue')}
function stockAction(s,kind){if(!kind){modal('Stock actions',`<p><b>${esc(s.coffee)}</b> · ${esc(s.code)}<br>${esc(s.location)} · ${esc(s.form)}</p><div class="action-grid">${stockActions(s,S.batches.find(b=>b.id===s.batch_id),admin()).map(([k,label])=>btn(label,'choose-move',{id:s.id,kind:k})).join('')}</div>${S.reservations.filter(r=>r.stock_id===s.id).map(r=>`<div class="list-row"><span>Reserved: ${grams(r.quantity_mg)} for ${esc(r.use)}</span>${btn('Release','release',{id:r.id},'small-btn')}</div>`).join('')}`,null);$('#modal').querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>b.dataset.action==='release'?action(b.dataset):stockAction(s,b.dataset.kind));return}
let body=notice(`<b>${esc(s.code)}</b> · ${esc(s.location)} · ${esc(s.form)}<br>${grams(s.quantity_mg+s.overfill_mg)} physically on hand /  ${grams(s.reserved_mg)} nominal reserved / ${grams(s.free_mg)} nominal free.`),title='',units=false;
if(kind==='transfer'){title='Transfer stock';body+=field(s.package_mg?'Whole bags to move':'Weight to move (g)',s.package_mg?'units':'grams','number','',`required min="${s.package_mg?1:0.001}" step="${s.package_mg?1:0.001}"`)+select('Destination','location_id',lo(s.location_id==='roastery'?'cafe':'roastery'));units=!!s.package_mg}
if(kind==='pack'){title='Pack bags';body+=select('Package','package_id',pa())+field('Whole bags','units','number','1','required min="1" step="1"')+select('Pack into','location_id',lo('packing'))+field('Packaging loss (g)','loss_g','number','0','min="0" step="0.001"')+field('Total overfill (g)','overfill_g','number','0','min="0" step="0.001"')+notice('Enter measured overfill for all bags, not per bag. It stays with the packaged stock through transfers and sales. Reservations and demand use the SKU’s nominal net content; physical on-hand includes measured overfill.')}
if(['consume','sale','waste','unpack','return'].includes(kind)){title={consume:'Record café consumption',sale:'Record a retail sale',waste:'Record waste / samples',unpack:'Open bags into bulk',return:'Confirm a physical return'}[kind];units=!!s.package_mg;body+=field(units?'Whole bags':'Measured quantity (g)',units?'units':'grams','number','',`required min="${units?1:0.001}" step="${units?1:0.001}"`);if(kind==='unpack')body+=select('Destination','location_id',lo('cafe'));if(kind==='consume')body+=notice('Use measured consumption for this period OR a remaining-weight count. Do not log the same usage using both methods.');if(kind==='return'&&s.package_mg)body+=field('Measured extra content in returned bags (g)','return_overfill_g','number','0','min="0" step="0.001"');if(kind==='return')body+=notice('Administrator only. The actual coffee must have been physically received. Select a quality-held batch; a refund alone is not a return.')}
if(['count','opening'].includes(kind)){title=kind==='count'?'Count remaining stock':'Confirm historical opening stock';units=!!s.package_mg;body+=field(units?'Counted whole bags':'Actual remaining net weight (g)',units?'count_units':'count_g','number',units?s.quantity_mg/s.package_mg:s.quantity_mg/1000,`required min="0" step="${units?1:0.001}"`)+notice('This count affects only this batch, location and form. It is rejected if another action changes this stock before you save. Enter what is physically here now; do not also deduct the same usage.')}
if(kind==='reserve'){title='Reserve stock';body+=select('Order line (or choose a requirement below)','line_id',options((isOrderStock(s)?S.orders:[]).flatMap(o=>o.lines.filter(l=>l.kind==='coffee'&&l.coffee_id===s.coffee_id&&l.unfulfilled).map(l=>[l.id,o.number+' · '+l.title+' · '+grams(l.missing_mg)+' unallocated'])),'',true))+select('Café / retail requirement','demand_id',options(S.demands.filter(d=>d.coffee_id===s.coffee_id).map(d=>[d.id,d.note+' · '+date(d.due_at)]),'',true))+select('Intended use','use',options([['dispatch','Online dispatch'],['brew','Café brewing'],['retail','Retail sale']]))+field('Weight to reserve (g)','grams','number','','required min="0.001" step="0.001"')+field('Required at (JST)','due_at','datetime-local',localInput(plus(2)),'required')+notice('Choose one order line or one requirement. Reservations keep physical stock in place and reduce free availability.')}
if(kind==='sale'&&S.settings.square_enabled)body+=notice('Square sales are imported automatically. Use this manual action only for a sale outside that import, to avoid a second deduction.');
body+=area('Reason / note'+(['count','opening','return'].includes(kind)?' (required)':''),'reason','',['count','opening','return'].includes(kind)?'required':'');modal(title,body,async(d,key)=>{let payload={...d,kind,stock_id:s.id,version:s.version};if(units){if(d.units!==undefined){if(!Number.isInteger(Number(d.units)))throw Error('Enter whole bags.');payload.grams=Number(d.units)*s.package_mg/1000}if(d.count_units!==undefined){if(!Number.isInteger(Number(d.count_units)))throw Error('Enter whole bags.');payload.count_g=Number(d.count_units)*s.package_mg/1000}}if(kind==='return')payload.count_g=s.quantity_mg/1000;if(d.due_at)payload.due_at=iso(d.due_at);await api('move',payload,key)},'Confirm '+kind);if(kind==='reserve'){
const line=$('#modal select[name=line_id]'),demand=$('#modal select[name=demand_id]'),due=$('#modal input[name=due_at]'),use=$('#modal select[name=use]');
line.onchange=()=>{if(line.value){demand.value='';const o=S.orders.find(o=>o.lines.some(l=>l.id===line.value));due.value=localInput(o.due_at);use.value='dispatch'}};
demand.onchange=()=>{if(demand.value){line.value='';const req=S.demands.find(r=>r.id===demand.value);due.value=localInput(req.due_at);use.value=req.channel}};
}}
function batchForm(plan){if(!S.coffees.some(c=>!c.archived)){toast('Add a coffee and rest policy in Settings first.',true);location.hash='settings';return}modal(plan?'Record completed planned roast':'Record a roast',notice('Measured green input is deducted from the linked green bean. Roasted output becomes roasted stock, with this batch’s rest policy.')+select('Coffee / profile','coffee_id',co(plan?.coffee_id))+field('Roasted at (JST)','roasted_at','datetime-local',localInput(clock()),'required')+field('Green input (g)','green_g','number',plan?plan.green_mg/1000:S.settings.charge_mg/1000,'required min="0.001" step="0.001"')+field('Actual roasted output (g)','output_g','number','','required min="0.001" step="0.001"')+field('Batch code (optional)','code')+field('Green lot (optional)','green_lot')+select('Initial location','location_id',lo())+recipeSelect(S,greenHelpers())+area('Notes / recipe override reason','notes'),async(d,key)=>api('batch',{...d,roasted_at:iso(d.roasted_at),...(plan?{plan_id:plan.id}:{})},key),'Record actual output')}
async function batchDetail(id){const b=S.batches.find(b=>b.id===id),h=await api('history?batch='+encodeURIComponent(id));modal(b.code,`<div class="batch-label">${logo}<span class="eyebrow">BATCH LABEL</span><h2>${esc(b.coffee)}</h2><strong>${esc(b.code)}</strong><p>Roasted ${date(b.roasted_at,true)} JST<br>Café ready ${date(b.readiness.brew.ready_at,true)} JST<br>${esc(b.profile)} · ${b.held?'QUALITY HOLD':'Check quality before use'}</p><small>${esc(location.origin+'/#batches/'+b.id)}</small></div><div class="quick-actions">${btn('Print batch label','print')}${btn('Edit notes','batch-notes',{id})}${!b.plan_id&&!b.history_only&&S.plans.some(p=>p.coffee_id===b.coffee_id&&p.status==='planned')?btn('Link completed plan','link-plan',{id}):''}${admin()&&b.stock_only?btn(b.roasted_at?'Edit roast date':'Set roast date','stock-date',{id}):''}${admin()?btn(b.held?'Release quality hold':'Place quality hold','hold',{id}):''}${admin()?btn('Review / override policy','policy',{id}):''}${admin()?btn(b.archived?'Restore from archive':'Archive as exception','archive',{id}):''}</div><div class="facts"><div><span>Applied café / dispatch / retail rest</span><b>${['brew_days','dispatch_days','retail_days'].map(k=>JSON.parse(b.policy)[k]??'unset').join(' / ')} days</b></div><div><span>Physical stock remaining</span><b>${grams(b.remaining_mg)}</b></div></div><p>${esc(b.notes)} ${b.hold_reason?'Quality decision: '+esc(b.hold_reason):''}</p>${batchRecipeDetails(b.blend,greenHelpers())}<h3>Movement ledger</h3><div class="table-wrap"><table><thead><tr><th>Action / time</th><th>Scope</th><th>Change</th><th>Actor / reason</th><th></th></tr></thead><tbody>${h.movements.map(m=>`<tr><td><b>${esc(m.kind)}</b><small>${date(m.at,true)}</small></td><td>${esc(S.locations.find(l=>l.id===m.location_id)?.name)}<small>${esc(m.package_id==='bulk'?'Bulk':S.packages.find(p=>p.id===m.package_id)?.name)}</small></td><td>${m.delta_mg>0?'+':''}${grams(m.delta_mg+m.delta_overfill_mg)}${m.delta_overfill_mg?`<small>Overfill ${grams(m.delta_overfill_mg)}</small>`:''}</td><td>${esc(m.actor)}<small>${esc(m.reason)}</small></td><td>${admin()&&!['shipment','reverse','square_sale'].includes(m.kind)?btn('Reverse','reverse',{id:m.id},'text-btn'):''}</td></tr>`).join('')}</tbody></table></div><details><summary>Recent audit decisions</summary>${h.audit.slice(0,40).map(a=>`<p><b>${esc(a.action)}</b> · ${esc(a.actor)} · ${date(a.at,true)}<small>${esc(a.detail)}</small></p>`).join('')}</details>`,null,'','large');$('#modal').querySelectorAll('[data-action]').forEach(el=>el.onclick=()=>action(el.dataset).catch(e=>toast(e.message,true)))}
function planForm(p={},suggestion){const green=suggestion?.charges_mg[0]||p.green_mg||S.settings.charge_mg;let when=suggestion?.latest_roast_at||p.roast_at||(localInput(plus(1)).slice(0,10)+'T'+S.settings.roast_slots[0]+':00+09:00');modal(suggestion?'Review a suggested roast':p.id?'Edit planned roast':'Schedule a roast',notice(suggestion?`Suggestion: ${grams(suggestion.shortage_mg)} uncovered. ${suggestion.charges_mg.length} batch(es) of ${kg(green)} suggested. Approve one charge at a time; the planner recalculates after each approval. ${suggestion.warnings.map(esc).join('. ')}`:'A planned roast is expected supply only. Record actual output when roasting is complete.')+select('Coffee','coffee_id',co(suggestion?.coffee_id||p.coffee_id))+field('Roast slot (JST)','roast_at','datetime-local',localInput(when),'required')+field('Green charge (g)','green_g','number',green/1000,'required min="0.001" step="0.001"')+field('Expected roasted output (g)','expected_g','number',p.expected_mg?p.expected_mg/1000:Math.floor(green*(suggestion?.yield_bp||8500)/10000)/1000,'required min="0.001" step="0.001"')+area('Reason / demand covered','explanation',p.explanation||(suggestion?`${suggestion.label}: ${grams(suggestion.shortage_mg)} uncovered; ${(suggestion.yield_bp/100).toFixed(1)}% ${suggestion.yield_source}`:''),'required'),async(d,key)=>api('plan',{...d,...(p.id?{id:p.id}:{}),roast_at:iso(d.roast_at)},key),'Approve planned batch')}
async function action(d){if(d.action.startsWith('blend-'))return blendAction(d,S,greenHelpers());if(['coffee-delete','coffee-restore'].includes(d.action))return coffeeVisibilityAction(d,S,greenHelpers());if(d.action.startsWith('profit-'))return profitAction(d,S,greenHelpers());if(d.action.startsWith('product-')||d.action.startsWith('square-'))return productAction(d,S,greenHelpers());if(d.action.startsWith('green-'))return greenAction(d,S,greenHelpers());switch(d.action){
case 'today-order':{const o=S.orders.find(o=>o.id===d.id);if(!o)return;orderFilters={sort:'due-first',source:'',status:'',fulfillment:'',payment:'',production:'',search:o.number};location.hash='orders';break;}
case 'clear-order-filters':orderFilters={sort:'newest',source:'',status:'',fulfillment:'',payment:'',production:'',search:''};draw();break;
case 'refresh':await refresh();break;
case 'logout':await api('logout',{});session=await api('session');loginScreen();break;
case 'settings-tab':tab=d.tab;if(location.hash!=='#settings/'+tab)location.hash='settings/'+tab;else draw();break;
case 'new-wholesale':wholesaleForm();break;
case 'edit-wholesale':wholesaleForm(S.orders.find(o=>o.id===d.id));break;
case 'wholesale-dispatch':{const o=S.orders.find(o=>o.id===d.id);fulfillmentForm({id:o.id,order:o,payload:JSON.stringify({lines:o.lines.filter(l=>l.unfulfilled).map(l=>({line_id:l.id,quantity:l.unfulfilled}))})},true);break;}
case 'count-stock-page':chooseStock('count',selectStocks(S.stocks,filters,localInput).map(s=>s.id));break;
case 'add-roasted-stock':addRoastedStockForm(S,greenHelpers());break;
case 'clear-stock-filters':filters={balance:'on-hand',use:'brew',coffee:'',location:'',form:'',reservation:'',readiness:'',date:''};draw();break;
case 'complete-imported-roast':{const r=S.pending_roasts.find(r=>r.external_id===d.id);if(r)completeRoastForm(r,S,greenHelpers());break;}
case 'new-batch':batchForm();break;
case 'complete-plan':batchForm(S.plans.find(p=>p.id===d.id));break;
case 'stock-action':stockAction(S.stocks.find(s=>s.id===d.id));break;
case 'choose-move':stockAction(S.stocks.find(s=>s.id===d.id),d.kind);break;
case 'quick-use':chooseStock('consume',S.stocks.filter(s=>s.location_id==='cafe'&&s.package_id==='bulk'&&s.quantity_mg).map(s=>s.id));break;
case 'quick-sale':chooseStock('sale',S.stocks.filter(s=>s.location_id==='wall'&&s.package_id!=='bulk'&&s.quantity_mg).map(s=>s.id));break;
case 'quick-count':chooseStock('count',d.location?S.stocks.filter(s=>s.location_id===d.location).map(s=>s.id):undefined);break;
case 'batch-detail':await batchDetail(d.id);break;
case 'print':window.print();break;
case 'batch-notes':{const b=S.batches.find(b=>b.id===d.id);modal('Local batch notes',area('Notes','notes',b.notes),x=>api('batch-notes',{id:b.id,notes:x.notes}));break;}
case 'hold':{const b=S.batches.find(b=>b.id===d.id);modal(b.held?'Release quality hold':'Place quality hold',area('Decision / reason','reason','','required')+notice('A hold keeps coffee in physical counts but prevents use and allocation. Existing commitments will be flagged.'),x=>api('batch-policy',{id:b.id,held:!b.held,reason:x.reason}));break}
case 'archive':{const b=S.batches.find(b=>b.id===d.id);modal(b.archived?'Restore batch':'Archive batch as exception',area('Reason','reason','','required'),x=>api('batch-policy',{id:b.id,archived:!b.archived,reason:x.reason}));break}
case 'stock-date':{const b=S.batches.find(b=>b.id===d.id);modal('Review stock-only roast date',notice('Enter the original roast date, not the date the coffee was found. Rest and freshness are recalculated without deducting green beans.')+field('Original roast date (JST)','roasted_at','datetime-local',localInput(b.roasted_at),'required max="'+localInput(clock())+'"')+area('Reason for date review','reason','','required'),x=>api('batch-policy',{id:b.id,roasted_at:iso(x.roasted_at),reason:x.reason}),'Save roast date');break;}
case 'policy':{const b=S.batches.find(b=>b.id===d.id),p=JSON.parse(b.policy);modal('Review batch rest policy',notice('Explicitly changing this batch can affect existing allocations. Check order deadlines before applying. Global coffee edits never alter this batch automatically.')+select('Action','mode',options([['override','Set explicit per-batch values'],['recalculate','Apply current coffee policy to this batch']]))+['brew','dispatch','retail','fresh'].map(k=>field(k==='fresh'?'Freshness window (days)':k+' rest (days)',k+'_days','number',p[k+'_days']??'','min="0" step="1"')).join('')+area('Override reason','reason','','required'),x=>api('batch-policy',{id:b.id,reason:x.reason,...(x.mode==='recalculate'?{recalculate:true}:{override:Object.fromEntries(['brew','dispatch','retail','fresh'].filter(k=>x[k+'_days']!=='').map(k=>[k+'_days',Number(x[k+'_days'])]))})}));break}
case 'reverse':modal('Reverse a ledger movement',notice('All entries in this movement are reversed together. The server rejects the correction if it would consume reserved stock or create a negative balance.')+area('Correction reason','reason','','required'),(x,key)=>api('move',{kind:'reverse',reversal_of:d.id,reason:x.reason},key),'Record reversal');break;
case 'order-date':{const o=S.orders.find(o=>o.id===d.id);modal('Set local deadline · '+o.number,field('Dispatch / pickup due (JST)','due_at','datetime-local',localInput(o.due_at),'required')+area('Local notes','notes',o.notes)+notice('This changes the operational deadline only. Shopify order, payment and fulfillment fields remain read-only.'),x=>api('order-local',{id:o.id,due_at:iso(x.due_at),notes:x.notes}));break}
case 'allocate':{const l=S.orders.flatMap(o=>o.lines).find(l=>l.id===d.id),o=S.orders.find(o=>o.id===l.order_id);const ss=orderAllocationStocks(S.stocks,l);if(!ss.length){toast('No free compatible stock at the roastery. Review the roast plan.',true);return}modal('Allocate · '+o.number,notice('Roastery stock only, oldest roast first. Allocate across multiple batches when needed. Eligibility is checked at the order deadline; quality holds always take precedence.')+select('Batch stock','stock_id',options(ss.map(s=>[s.id,`${s.code} · ${s.location} · ${s.form} · ${grams(s.free_mg)} free · ${s.readiness.dispatch.label}`])))+field('Weight to reserve (g)','grams','number',l.missing_mg/1000,'required min="0.001" step="0.001"')+field('Dispatch due (JST)','due_at','datetime-local',localInput(o.due_at),'required'),(x,key)=>api('move',{...x,kind:'reserve',line_id:l.id,use:'dispatch',due_at:iso(x.due_at)},key),'Reserve stock');break}
case 'allocations':{const rs=S.reservations.filter(r=>r.line_id===d.line);modal('Manage allocations',rs.map(r=>`<div class="list-row"><div><b>${esc(r.code)}</b><small>${grams(r.quantity_mg)} · ${esc(S.stocks.find(s=>s.id===r.stock_id)?.location)} · due ${date(r.due_at,true)}</small></div>${btn('Release','release',{id:r.id},'small-btn')}</div>`).join(''),null);$('#modal').querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset).catch(e=>toast(e.message,true)));break}
case 'release':{const r=S.reservations.find(r=>r.id===d.id);modal('Release reservation',notice(`Release ${grams(r.quantity_mg)} from ${esc(r.code)}. Physical on-hand quantity will not increase.`)+area('Reason','reason'),(x,key)=>api('move',{kind:'release',stock_id:r.stock_id,reservation_id:r.id,reason:x.reason},key),'Release');break}
case 'pack-reservation':{const r=S.reservations.find(r=>r.id===d.id);modal('Pack order allocation',notice(`${grams(r.quantity_mg)} of reserved bulk will become whole bags of the order’s mapped package size. The reservation moves with the coffee. For loss/overfill, release and repack explicitly before reallocating.`)+select('Destination','location_id',options(S.locations.filter(l=>l.id==='roastery').map(l=>[l.id,l.name]),'roastery')),(x,key)=>api('move',{kind:'pack_reserved',stock_id:r.stock_id,reservation_id:r.id,location_id:x.location_id},key),'Pack allocated coffee');break}
case 'fulfillment':fulfillmentForm(S.fulfillments.find(f=>f.id===d.id));break;
case 'link-plan':{const b=S.batches.find(b=>b.id===d.id);modal('Link actual batch to its roast plan',notice('This batch already created physical stock. Linking replaces the plan’s expected supply with this existing measured output; no additional stock is created.')+select('Matching open plan','plan_id',options(S.plans.filter(p=>p.coffee_id===b.coffee_id&&p.status==='planned').map(p=>[p.id,date(p.roast_at,true)+' · '+grams(p.green_mg)+' green'])))+area('Match confirmation / reason','reason','','required'),(x,key)=>api('link-plan',{batch_id:b.id,...x},key),'Link completion');break;}
case 'new-plan':planForm();break;
case 'edit-plan':planForm(S.plans.find(p=>p.id===d.id));break;
case 'suggestion':planForm({},S.planner.rows.find(r=>r.id===d.id));break;
case 'cancel-plan':modal('Cancel planned roast',notice('Expected supply will be removed from the planner. No physical stock changes.')+area('Reason','reason'),x=>api('plan-cancel',{id:d.id,...x}),'Cancel roast');break;
case 'new-demand':case 'edit-demand':{const req=S.demands.find(r=>r.id===d.id)||{};modal(req.id?'Edit requirement':'Add a dated requirement',select('Coffee','coffee_id',co(req.coffee_id))+select('Destination','channel',options([['brew','Café consumption forecast'],['retail','Desired total retail stock']],req.channel))+field('Required quantity (g)','grams','number',req.quantity_mg?req.quantity_mg/1000:'','required min="0.001" step="0.001"')+field('Required at (JST)','due_at','datetime-local',localInput(req.due_at||plus(7)),'required')+area('Description','note',req.note||'')+notice('Enter a one-off café consumption requirement or total wall target for this date. Do not repeat the same minimum stock target as daily fresh demand.'),x=>api('demand',{...x,...(req.id?{id:req.id}:{}),due_at:iso(x.due_at)}));break}
case 'delete-demand':modal('Remove forecast / target',notice('This removes planned demand only. Release any related reservations first.'),()=>api('demand',{id:d.id,delete:true}),'Remove');break;
case 'coffee':case 'new-coffee':{const c=S.coffees.find(c=>c.id===d.id)||{brew_days:45,dispatch_days:'',retail_days:'',fresh_days:75,yield_bp:8500};modal(c.id?'Edit coffee policy':'Add a coffee / profile',field('Coffee name','name','text',c.name||'','required')+field('Profile / intended brew','profile','text',c.profile||'Pour-over','required')+field('Café minimum rest (elapsed days)','brew_days','number',c.brew_days,'required min="0" step="1"')+field('Dispatch minimum rest (days; blank = unset)','dispatch_days','number',c.dispatch_days??'','min="0" step="1"')+field('Retail minimum rest (days; blank = unset)','retail_days','number',c.retail_days??'','min="0" step="1"')+field('Freshness window (days; quality policy)','fresh_days','number',c.fresh_days,'required min="1" step="1"')+field('Fallback yield (%)','yield_percent','number',c.yield_bp/100,'required min="0.01" max="100" step="0.01"')+notice('Your café guidance is 45 days for pour-over and 7 days for espresso. Confirm by bean. Dispatch, retail, freshness and fallback yield values must be reviewed. Existing batch policies stay unchanged.'),x=>api('coffee',{...x,...(c.id?{id:c.id}:{}),yield_bp:Math.round(Number(x.yield_percent)*100)}));break}
case 'package':modal('Add package definition',field('Package name','name','text','','required')+field('Nominal net weight (g)','grams','number','','required min="0.001" step="0.001"'),x=>api('package',x));break;
case 'location':modal('Add location or container',field('Name (for example Café hopper 1)','name','text','','required'),x=>api('location',x));break;
case 'variant':{const v=S.variants.find(v=>v.id===d.id);modal('Map stable Shopify variant',notice(esc(v.id)+'<br>Bundle/sample-box compositions must remain unresolved until explicitly modeled. No coffee is inferred from a mutable name.')+select('Classification','kind',options([['coffee','Coffee'],['noncoffee','Non-coffee merchandise'],['unresolved','Unresolved bundle / unknown']],v.kind))+select('Coffee / profile','coffee_id',co(v.coffee_id,true))+select('Package','package_id',pa(v.package_id,true))+field('Grind option','grind','text',v.grind),x=>api('variant',{id:v.id,...x}));break}
case 'bean-map':modal('Map Roast.World bean',field('Exact external bean ID','external_id','text','','required')+select('Coffee / profile','coffee_id',co())+notice('After mapping, complete pending imports from Roast batches. This does not rewrite batches already imported.'),x=>api('bean-map',x));break;
case 'planning-settings':{const c=S.settings;modal('Planning assumptions',field('Working charge (g)','charge','number',c.charge_mg/1000,'required min="0.001" step="0.001"')+field('Confirmed maximum charge (g)','max','number',c.max_charge_mg/1000,'required min="0.001" step="0.001"')+field('Roast weekdays (Mon=0 … Sun=6, comma separated)','days','text',c.roast_days.join(','),'required')+field('Roast start slots (JST, comma separated HH:MM)','slots','text',c.roast_slots.join(','),'required')+field('Packing / delivery buffer (whole days)','buffer_days','number',c.buffer_days,'required min="0" step="1"')+field('Safety buffer (%)','safety','number',c.safety_bp/100,'required min="0" step="0.01"')+field('Priority (comma separated: dispatch,brew,retail)','priorities','text',c.channel_priority.join(','),'required'),x=>api('settings',{charge_mg:Math.round(Number(x.charge)*1000),max_charge_mg:Math.round(Number(x.max)*1000),roast_days:x.days.split(',').map(Number),roast_slots:x.slots.split(',').map(t=>t.trim()),roast_days_confirmed:true,buffer_days:Number(x.buffer_days),safety_bp:Math.round(Number(x.safety)*100),channel_priority:x.priorities.split(',').map(s=>s.trim())}));break}
case 'connection-settings':modal('Cutover & connection policy',field('Import roasts from (JST; blank = all history)','roastworld_start_at','datetime-local',localInput(S.settings.roastworld_start_at))+field('Cutover timestamp (JST; blank = history only)','cutover_at','datetime-local',localInput(S.settings.cutover_at))+field('Polling interval (seconds)','poll_seconds','number',S.settings.poll_seconds,'required min="60" step="1"')+field('Eligible Shopify payment states (comma separated)','payments','text',S.settings.eligible_payments.join(','),'required')+notice('The import start ignores earlier unposted roast records. Changing either date does not repost production or alter stock history. Confirm opening counts for any historical coffee still on hand. Payment eligibility affects future allocation and planning.'),x=>api('settings',{cutover_at:iso(x.cutover_at),roastworld_start_at:iso(x.roastworld_start_at),poll_seconds:Number(x.poll_seconds),eligible_payments:x.payments.split(',').map(v=>v.trim())}));break;
case 'sync':await api('sync',{source:d.source});toast('Sync queued. Results will appear here.');setTimeout(()=>refresh().catch(()=>{}),1500);break;
case 'retry-import':await api('retry-import',{external_id:d.id});await refresh();toast('Import reviewed. Check remaining exceptions.');break;
case 'resolve':modal('Document reconciliation',notice('Resolve only after reviewing the actual source and physical stock. This note does not invent a stock movement; record any required correction separately.')+area('Resolution and supporting count / movement','reason','','required'),x=>api('issue',{id:d.id,reason:x.reason}),'Resolve exception');break;
case 'user':{const u=S.users.find(u=>u.id===d.id);const body=(u?`<p><b>${esc(u.name)}</b></p>`:field('Username','name','text','','required autocomplete="off"'))+field(u?'Reset password (optional)':'Initial password (12+ characters)','password','password','',`${u?'':'required'} minlength="12" autocomplete="new-password"`)+select('Role','role',options([['staff','Staff'],['admin','Administrator']],u?.role||'staff'))+(u?select('Access','active',options([['1','Active'],['0','Disabled']],String(u.active))):'');modal(u?'Manage account':'Add staff account',body,x=>api('user',{...x,...(u?{id:u.id,active:x.active==='1'}:{})}));break}
case 'csv-template':download('walnuts-roast-import-template.csv','external_id,bean_id,roasted_at,green_g,output_g\nexample-unique-roast,external-bean-id,2026-11-05T10:00:00+09:00,1000,850\n','text/csv');break;
case 'csv':csvDialog();break;
case 'export':{const result=await api('export');download('walnuts-ledger-'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify(result,null,2),'application/json');break}
case 'order-import':modal('Import normalized order file',notice('Administrative fallback for your own exported order data. Use the documented normalized fixture schema. This does not claim Shopify is connected; source IDs must be stable and status fields must reflect the actual source.')+area('Normalized order JSON','json','','required'),x=>api('order-import',JSON.parse(x.json)),'Validate & import');break;
}}
function wholesaleForm(order){
 if(!S.coffees.some(c=>!c.archived)){modal('Set up coffees first',notice('Add your actual coffees and rest policies under Settings → Coffees before entering wholesale demand. Then return here to create the order.'),null);return}
 const w=order?.wholesale||{},customer=w.customer||{};let count=0,rows=[];
 function lineFields(line={}){
  const n=count++,variant=S.variants.find(v=>v.id===line.variant_id),size=S.packages.find(p=>p.id===(line.package_id||variant?.package_id));
  rows.push({n,id:line.id,package_id:size?.id,weight_mg:size?.weight_mg});
  return `<section class="wholesale-line" data-wholesale-row="${n}"><div class="line-heading"><h3>Coffee line ${n+1}</h3><button type="button" class="text-btn" data-remove-wholesale="${n}">Remove line</button></div>${select('Coffee / profile','coffee_'+n,co(line.coffee_id||variant?.coffee_id))}${field('Weight per bag (g)','weight_'+n,'number',size?size.weight_mg/1000:'','required min="0.001" step="0.001"')}${field('Number of bags','quantity_'+n,'number',line.quantity||1,'required min="1" max="10000" step="1"')}${field('Grind / preparation','grind_'+n,'text',variant?.grind||'Whole bean')}<small>Line total: <b data-line-total="${n}">—</b>${line.quantity>line.unfulfilled?' · '+(line.quantity-line.unfulfilled)+' bags already dispatched':''}</small></section>`
 }
 modal(order?'Edit wholesale order':'New wholesale order',
 notice('Confirmed orders enter production planning using each coffee’s dispatch-rest policy, including orders on invoice terms. Drafts are saved without committing production. Quantities are whole bags; enter the actual bag size in grams.')+
 field('Customer / business name','business','text',customer.business||'','required maxlength="200"')+field('Contact person','contact','text',customer.contact||'','maxlength="200"')+
 field('Email','email','email',customer.email||'')+field('Phone','phone','tel',customer.phone||'')+
 area('Delivery address / instructions','address',customer.address||'')+
 field('Purchase order / reference','reference','text',w.reference||'')+field('Payment terms','terms','text',w.terms||'')+
 select('Order status','status',options([['CONFIRMED','Confirmed — include in roast plan'],['DRAFT','Draft'],['CANCELLED','Cancelled']],w.status||'CONFIRMED'))+
 select('Payment status','payment',options([['PENDING','Awaiting payment / invoice'],['PAID','Paid'],['PARTIALLY_PAID','Partially paid'],['REFUNDED','Refunded']],order?.payment||'PENDING'))+
 select('Delivery method','method',options([['delivery','Delivery'],['pickup','Pickup']],order?.delivery==='Pickup'?'pickup':'delivery'))+
 field('Dispatch / pickup deadline (JST)','due_at','datetime-local',localInput(order?.due_at||plus(7)))+
 `<div class="wholesale-lines">${(order?.lines||[{}]).map(lineFields).join('')}</div><div class="quick-actions"><button type="button" class="secondary" id="add-wholesale-line">+ Add another coffee</button></div>`+
 area('Order notes','notes',order?.notes||''),async(x,key)=>{
  const payload={...(order?{id:order.id,version:w.version}:{}),customer:Object.fromEntries(['business','contact','email','phone','address'].map(k=>[k,x[k]])),reference:x.reference,terms:x.terms,status:x.status,payment:x.payment,method:x.method,due_at:iso(x.due_at),notes:x.notes,
  lines:rows.map(r=>({...(r.id?{id:r.id}:{}),coffee_id:x['coffee_'+r.n],...(r.package_id&&Math.round(Number(x['weight_'+r.n])*1000)===r.weight_mg?{package_id:r.package_id}:{}),unit_g:x['weight_'+r.n],quantity:x['quantity_'+r.n],grind:x['grind_'+r.n]}))};
  await api('wholesale',payload,key);
 },'Save wholesale order','large');
 function update(){for(const r of rows){const q=Number($('#modal [name=quantity_'+r.n+']')?.value),g=Number($('#modal [name=weight_'+r.n+']')?.value);const target=$('#modal [data-line-total="'+r.n+'"]');if(target)target.textContent=q&&g?grams(Math.round(q*g*1000)):'—'}}
 function bindLines(){
  $('#modal').querySelectorAll('[data-remove-wholesale]').forEach(b=>b.onclick=()=>{const n=Number(b.dataset.removeWholesale);$('#modal [data-wholesale-row="'+n+'"]').remove();rows=rows.filter(r=>r.n!==n)});
  $('#modal').querySelectorAll('.wholesale-line input').forEach(el=>el.oninput=update);update();
 }
 $('#add-wholesale-line').onclick=()=>{$('#modal .wholesale-lines').insertAdjacentHTML('beforeend',lineFields());bindLines()};bindLines();
}
function fulfillmentForm(f,wholesale=false){
const items=JSON.parse(f.payload).lines.map(i=>({...i,line:S.orders.flatMap(o=>o.lines).find(l=>l.id===i.line_id)})).filter(i=>i.line?.kind!=='noncoffee');
if(items.some(i=>!i.line||i.line.kind!=='coffee')){toast('Map the remaining variants before recording a pick.',true);return}
let counter=0;const choices=[];
function pickFields(item){const n=counter++,p=S.packages.find(p=>p.id===item.line.package_id);choices[n]={line:item.line_id,size:p.weight_mg};const available=S.stocks.filter(s=>s.coffee_id===item.line.coffee_id&&s.package_id===p.id&&(s.free_mg+(wholesale?S.reservations.filter(r=>r.line_id===item.line_id&&r.stock_id===s.id).reduce((a,r)=>a+r.quantity_mg,0):0))>0).sort(compareStockAge);return `<div class="pick-row wide"><h3>${esc(item.line.title)} · ${item.quantity} ${wholesale?'remaining bags':'confirmed units'}</h3>${select('Actual batch picked','stock_'+n,options(available.map(s=>[s.id,`${s.code} · ${s.location} · ${(s.free_mg+(wholesale?S.reservations.filter(r=>r.line_id===item.line_id&&r.stock_id===s.id).reduce((a,r)=>a+r.quantity_mg,0):0))/p.weight_mg} bags available · ${s.readiness.dispatch.label}`]),'',true))}${field('Whole bags picked','units_'+n,'number','0','required min="0" step="1"')}</div>`}
modal(wholesale?'Record wholesale dispatch':'Record the actual shipment pick',notice(wholesale?'Choose the actual packed batches being delivered or collected. Partial dispatches are allowed. Only picked stock is deducted; remaining quantities stay open. Leave unused rows at zero.':'Shopify already confirms this shipment. Choose the batches physically picked. This neither fulfills an order nor sends a notification. Leave unused rows at zero.')+items.map(i=>pickFields(i)).join('')+`<div class="quick-actions">${items.map((i,n)=>`<button type="button" class="secondary" data-add-pick="${n}">+ Another batch for ${esc(i.line.title)}</button>`).join('')}</div>`,async(x,key)=>{const picks=choices.flatMap((c,n)=>{const units=Number(x['units_'+n]);if(!Number.isInteger(units)||units<0)throw Error('Pick whole bags.');if(!units)return [];if(!x['stock_'+n])throw Error('Select the actual batch picked.');return [{line_id:c.line,stock_id:x['stock_'+n],grams:units*c.size/1000}]});await api(wholesale?'wholesale-dispatch':'fulfillment-pick',wholesale?{order_id:f.order.id,version:f.order.wholesale.version,picks}:{fulfillment_id:f.id,picks},key)},wholesale?'Confirm dispatch':'Confirm physical pick');
$('#modal').querySelectorAll('[data-add-pick]').forEach(b=>b.onclick=()=>{$('#modal .quick-actions').insertAdjacentHTML('beforebegin',pickFields(items[Number(b.dataset.addPick)]))})
}
function csvDialog(){modal('Preview roast CSV import',notice('Use the supplied template. This is not claimed to match an uninspected RoasTime export. Historic rows stay history-only; missing weights are rejected.')+area('Paste CSV','csv','','required')+`<button type="button" class="secondary" id="csv-check">Validate preview</button><div id="csv-results"></div>`,async x=>{if(!$('#csv-check').dataset.valid||$('#csv-check').dataset.hash!==x.csv)throw Error('Validate this exact CSV before importing.');await api('csv-commit',{csv:x.csv})},'Import validated rows');$('#csv-check').onclick=async()=>{try{const text=$('#modal textarea').value,r=await api('csv-preview',{csv:text});$('#csv-results').innerHTML=r.rows.map(row=>`<div class="list-row"><b>Row ${row.row}: ${esc(row.external_id)}</b>${badge(row.errors.length?row.errors.join('; '):row.duplicate?'Existing ID — no duplicate production':'Valid',row.errors.length?'red':'green')}</div>`).join('');$('#csv-check').dataset.valid=r.rows.every(r=>!r.errors.length)?'yes':'';$('#csv-check').dataset.hash=text}catch(e){$('#csv-results').textContent=e.message}}}
function download(name,text,type){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
window.addEventListener('hashchange',()=>{const route=routeForHash(location.hash,tab);view=route.view;tab=route.tab;if(route.hash)history.replaceState(null,'',route.hash);if(S){draw();if(view==='batches'&&route.detail)batchDetail(route.detail).catch(e=>toast(e.message,true))}});
window.addEventListener('offline',()=>{disconnected=true;if(S)draw()});window.addEventListener('online',()=>refresh().catch(()=>{}));
async function start(){try{const r=await api('session');session=r.user||r;if(r.user){await refresh();const id=location.hash.split('/')[1];if(id&&view==='batches')await batchDetail(id)}else loginScreen()}catch{ $('#app').innerHTML=empty('Cannot reach the roastery server','Start the server, then reload this page. No stock action was saved.')}}
setInterval(()=>{if(S&&session?.csrf&&!$('#modal').open&&!busy)refresh().catch(()=>{})},30000);
start();
